"use strict";(self.webpackChunkmindstack=self.webpackChunkmindstack||[]).push([["2713"],{451(e,n,t){t.r(n),t.d(n,{metadata:()=>s,default:()=>h,frontMatter:()=>a,contentTitle:()=>o,toc:()=>c,assets:()=>l});var s=JSON.parse('{"id":"SoftwareEngineering/event-driven-architecture","title":"Event-Driven Architecture","description":"Instead of components calling each other directly and waiting for a response, event-driven systems communicate by publishing facts (\\"this happened\\") that interested parties can react to independently. This page covers message queues, pub/sub, event sourcing, and CQRS.","source":"@site/docs/SoftwareEngineering/12-event-driven-architecture.md","sourceDirName":"SoftwareEngineering","slug":"/SoftwareEngineering/event-driven-architecture","permalink":"/Mindstack/docs/SoftwareEngineering/event-driven-architecture","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":12,"frontMatter":{"title":"Event-Driven Architecture","sidebar_label":"Event-Driven Architecture","sidebar_position":12},"sidebar":"softwareEngineeringSidebar","previous":{"title":"Modular Monolith","permalink":"/Mindstack/docs/SoftwareEngineering/modular-monolith"},"next":{"title":"Architectural Patterns","permalink":"/Mindstack/docs/SoftwareEngineering/architectural-patterns"}}'),i=t(4848),r=t(8453);let a={title:"Event-Driven Architecture",sidebar_label:"Event-Driven Architecture",sidebar_position:12},o="Event-Driven Architecture",l={},c=[{value:"The Core Shift in Thinking",id:"the-core-shift-in-thinking",level:2},{value:"Message Queues \u2014 Point-to-Point",id:"message-queues--point-to-point",level:2},{value:"Publish/Subscribe \u2014 One-to-Many",id:"publishsubscribe--one-to-many",level:2},{value:"Choosing Between Queue and Pub/Sub",id:"choosing-between-queue-and-pubsub",level:2},{value:"Delivery Guarantees",id:"delivery-guarantees",level:2},{value:"Event Sourcing",id:"event-sourcing",level:2},{value:"CQRS \u2014 Command Query Responsibility Segregation",id:"cqrs--command-query-responsibility-segregation",level:2},{value:"Tips",id:"tips",level:2},{value:"Summary",id:"summary",level:2}];function d(e){let n={code:"code",h1:"h1",h2:"h2",header:"header",hr:"hr",li:"li",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,r.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"event-driven-architecture",children:"Event-Driven Architecture"})}),"\n",(0,i.jsx)(n.p,{children:'Instead of components calling each other directly and waiting for a response, event-driven systems communicate by publishing facts ("this happened") that interested parties can react to independently. This page covers message queues, pub/sub, event sourcing, and CQRS.'}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"the-core-shift-in-thinking",children:"The Core Shift in Thinking"}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:'Request/response thinking:\n  "Call the Shipping Service and tell it to schedule a delivery."\n  The caller knows exactly who needs to act, and calls them directly.\n\nEvent-driven thinking:\n  "Announce that an order was placed. Whoever cares can react."\n  The caller doesn\'t know or care who\'s listening \u2014 today it might be\n  Shipping and Analytics; next month a new Fraud Detection service\n  can start listening too, with ZERO change to the code that publishes\n  the event.\n\nThis is the Observer pattern (file 06) applied at the scale of an\nentire system rather than within a single process.\n'})}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"message-queues--point-to-point",children:"Message Queues \u2014 Point-to-Point"}),"\n",(0,i.jsx)(n.p,{children:"A queue holds messages until exactly one consumer processes each one. Useful for distributing work across a pool of workers."}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:"   Producer                  Queue                  Workers\n      \u2502                        \u2502                        \u2502\n      \u2502 \u2500\u2500 send(job) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500> \u2502                        \u2502\n      \u2502 \u2500\u2500 send(job) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500> \u2502\u2500\u2500\u2500\u2500 job#1 \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500>\u2502 Worker A\n      \u2502 \u2500\u2500 send(job) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500> \u2502\u2500\u2500\u2500\u2500 job#2 \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500>\u2502 Worker B\n      \u2502                        \u2502\u2500\u2500\u2500\u2500 job#3 \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500>\u2502 Worker A (free again)\n\nEach message is delivered to and processed by exactly ONE worker \u2014\nthis is the classic pattern for distributing a workload (see the\nworker pool pattern in the Go course's concurrency page \u2014 this is the\nsame idea at the system level, across multiple processes/machines\ninstead of goroutines within one process).\n"})}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Common technologies:"})," RabbitMQ, Amazon SQS, Google Cloud Pub/Sub (in queue mode)."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Use for:"})," background job processing (image resizing, PDF generation, sending emails), work that can be processed asynchronously and load-balanced across a pool of workers."]}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"publishsubscribe--one-to-many",children:"Publish/Subscribe \u2014 One-to-Many"}),"\n",(0,i.jsx)(n.p,{children:"A publisher broadcasts an event; every subscriber that's registered interest receives its own copy."}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:'                            Topic: "OrderPlaced"\n                                   \u2502\n   Publisher                       \u2502\n      \u2502                            \u2502\n      \u2502 \u2500\u2500 publish(event) \u2500\u2500\u2500\u2500\u2500\u2500\u2500> \u2502\n      \u2502                            \u251C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500> Shipping Service\n      \u2502                            \u251C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500> Analytics Service\n      \u2502                            \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500> Fraud Detection Service\n\nEvery subscriber gets EVERY message \u2014 unlike a queue, where each\nmessage goes to exactly one consumer.\n'})}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Common technologies:"})," Apache Kafka, Google Cloud Pub/Sub (in pub/sub mode), AWS SNS, Redis Pub/Sub."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Use for:"})," broadcasting a fact that multiple, independent, decoupled parts of the system need to react to \u2014 the publisher doesn't need to know who's listening, or how many listeners there are."]}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"choosing-between-queue-and-pubsub",children:"Choosing Between Queue and Pub/Sub"}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:'Ask: "should each message be handled by exactly ONE consumer, or\nshould EVERY interested consumer get their own copy?"\n\nDistribute work across a pool (each job done once, by whichever\n  worker picks it up)                              \u2192 Queue\n\nBroadcast a fact that multiple independent systems\n  each need to react to in their own way             \u2192 Pub/Sub\n\nSome real systems (Kafka especially) support both patterns at once,\nvia CONSUMER GROUPS: within one group, messages are load-balanced\nacross the group\'s members like a queue; across DIFFERENT groups,\neach group gets its own full copy of every message, like pub/sub.\n'})}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"delivery-guarantees",children:"Delivery Guarantees"}),"\n",(0,i.jsx)(n.p,{children:"A critical, easy-to-overlook design decision \u2014 different messaging systems (and different configurations of the same system) offer different guarantees, and the difference has real consequences."}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:"At-most-once:\n  A message might be lost, but is never delivered twice.\n  Fastest, simplest \u2014 acceptable for data where an occasional loss\n  is tolerable (some metrics/analytics events, perhaps).\n\nAt-least-once:\n  A message is never lost, but might be delivered more than once\n  (e.g. if a consumer crashes after processing but before\n  acknowledging receipt, the message is redelivered).\n  The most common guarantee in practice \u2014 but it means every consumer\n  MUST be written to handle duplicate delivery safely.\n\nExactly-once:\n  Genuinely difficult to guarantee across a distributed system in the\n  general case; most systems that claim it actually provide\n  at-least-once delivery PLUS deduplication (tracking which message\n  IDs have already been processed) to achieve the same practical effect.\n"})}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-python",children:"# Because at-least-once delivery is the common case, consumers should\n# be IDEMPOTENT \u2014 processing the same message twice should have the\n# same effect as processing it once (the same idea as the idempotency\n# key pattern in file 08, API Design, applied to message consumers)\n\ndef handle_order_placed_event(event):\n    if already_processed(event.id):     # deduplication check\n        return\n    process_order(event)\n    mark_as_processed(event.id)\n"})}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"event-sourcing",children:"Event Sourcing"}),"\n",(0,i.jsx)(n.p,{children:"Instead of storing only the CURRENT state of an entity, event sourcing stores the full sequence of events that led to that state \u2014 the current state is derived by replaying them."}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:"Traditional approach \u2014 store current state only:\n  accounts table:\n    account_id | balance\n    ACC-001    | 150\n\n  You know the balance is 150. You don't know HOW it got there,\n  unless you separately logged that history somewhere else.\n\nEvent sourcing \u2014 store the sequence of events, derive state from them:\n  events table:\n    account_id | event              | amount\n    ACC-001    | AccountOpened      | 0\n    ACC-001    | MoneyDeposited     | 100\n    ACC-001    | MoneyDeposited     | 75\n    ACC-001    | MoneyWithdrawn     | 25\n\n  Current balance is DERIVED: 0 + 100 + 75 - 25 = 150\n\n  The events themselves are the source of truth \u2014 immutable, append-only.\n"})}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-python",children:"class Account:\n    def __init__(self):\n        self.balance = 0\n        self._uncommitted_events = []\n\n    def deposit(self, amount):\n        event = MoneyDeposited(amount)\n        self._apply(event)\n        self._uncommitted_events.append(event)\n\n    def _apply(self, event):\n        if isinstance(event, MoneyDeposited):\n            self.balance += event.amount\n        elif isinstance(event, MoneyWithdrawn):\n            self.balance -= event.amount\n\n    @classmethod\n    def from_events(cls, events):\n        account = cls()\n        for event in events:\n            account._apply(event)          # replay history to rebuild current state\n        return account\n"})}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Benefits:"}),' a complete, genuine audit trail (valuable for finance, healthcare, compliance-heavy domains); the ability to answer "what was the state at any point in the past" by replaying events up to that point; new ways of deriving insight from history that weren\'t anticipated when the events were originally recorded.']}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Costs:"}),' genuinely more complex than simply storing current state; querying "current state" requires either replaying events (slow for a long history) or maintaining a separate, continuously-updated read model (see CQRS, below); the event schema itself becomes something you need to version carefully over the system\'s lifetime, since old events must remain replayable.']}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Use when:"}),' the audit trail itself has real business value (financial ledgers, healthcare records, anything where "how did we get to this state" matters, not just "what is the state now"). Overkill for most simple CRUD needs.']}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"cqrs--command-query-responsibility-segregation",children:"CQRS \u2014 Command Query Responsibility Segregation"}),"\n",(0,i.jsx)(n.p,{children:"Separates the model used to WRITE data (commands) from the model used to READ data (queries) \u2014 they don't have to be the same shape, or even the same database."}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:"Traditional (one model for both read and write):\n\n   Client                    Application               Database\n      \u2502                          \u2502                          \u2502\n      \u2502 \u2500\u2500 write request \u2500\u2500\u2500\u2500\u2500\u2500> \u2502 \u2500\u2500 write \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500>\u2502\n      \u2502 \u2500\u2500 read request \u2500\u2500\u2500\u2500\u2500\u2500\u2500> \u2502 \u2500\u2500 read \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500>\u2502\n                                   (same model, same DB, both directions)\n\nCQRS (separate models):\n\n   Client              Command Side              Write Database\n      \u2502                     \u2502                          \u2502\n      \u2502 \u2500\u2500 command \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500>\u2502 \u2500\u2500 write \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500>\u2502\n                                                          \u2502\n                                                    (sync via events)\n                                                          \u2502\n   Client               Query Side               Read Database\n      \u2502                     \u2502                          \u2502  (denormalized,\n      \u2502 \u2500\u2500 query \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500>\u2502 \u2500\u2500 read \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500>\u2502   optimized for\n                                                             fast reads)\n"})}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Why split them:"}),' write operations often care about strict validation and business rules (a "command" like ',(0,i.jsx)(n.code,{children:"PlaceOrder"})," needs to enforce invariants); read operations often care about fast, flexible querying across denormalized, pre-joined data (a dashboard showing orders-with-customer-names-and-shipping-status benefits from a read model that's already shaped exactly like the UI needs, instead of joining five tables on every request)."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Cost:"})," genuine added complexity \u2014 two models to maintain, and the read model is only as fresh as the last sync from the write side (eventual consistency, see file 17) \u2014 a write might not be immediately visible in the read model."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"CQRS and Event Sourcing often pair together:"})," events from the write side are exactly what naturally populates and updates the read side's denormalized views, keeping the two in sync as events occur."]}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:"Use CQRS when: read and write patterns are GENUINELY different enough\nto benefit from separate models \u2014 high-read, reporting-heavy systems\nwith complex write-side business rules are the classic fit.\n\nSkip CQRS when: a simple CRUD application where reads and writes\nnaturally share the same shape \u2014 the added complexity isn't repaid,\nsame judgment call as DDD's tactical patterns (file 07) and the\nYAGNI principle (file 04).\n"})}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"tips",children:"Tips"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Choose queue vs pub/sub based on one question: does each message need exactly one handler (queue), or does every interested party need its own copy (pub/sub)?"}),"\n",(0,i.jsx)(n.li,{children:"Design every event consumer to be idempotent \u2014 at-least-once delivery is the realistic default for most messaging systems, and a consumer that can't safely handle duplicate delivery will eventually cause a real bug."}),"\n",(0,i.jsx)(n.li,{children:"Event sourcing and CQRS are powerful but genuinely add complexity \u2014 reach for them when the audit trail or the read/write split has real, demonstrated business value, not as a default architecture choice."}),"\n",(0,i.jsx)(n.li,{children:"Event-driven systems trade immediate consistency for loose coupling and resilience \u2014 make sure the parts of your system that genuinely need immediate consistency (like checking current stock before confirming a sale) use synchronous calls instead (see file 10)."}),"\n"]}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"summary",children:"Summary"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Event-driven architecture replaces direct calls with published facts that interested parties react to independently \u2014 the system-level version of the Observer pattern (file 06)."}),"\n",(0,i.jsx)(n.li,{children:"Queues deliver each message to exactly one consumer (work distribution); pub/sub delivers each message to every subscriber (broadcasting a fact)."}),"\n",(0,i.jsx)(n.li,{children:"At-least-once delivery is the common real-world guarantee \u2014 design consumers to be idempotent to handle occasional duplicate delivery safely."}),"\n",(0,i.jsx)(n.li,{children:"Event sourcing stores the full history of events (not just current state) as the source of truth \u2014 valuable for audit-heavy domains, genuine added complexity for simple ones."}),"\n",(0,i.jsx)(n.li,{children:"CQRS separates write models (enforcing business rules) from read models (optimized for fast, flexible querying) \u2014 often paired with event sourcing, at the cost of eventual consistency between the two sides."}),"\n",(0,i.jsx)(n.li,{children:"Both event sourcing and CQRS are judgment calls, not defaults \u2014 apply them where their specific benefits are actually needed, echoing the YAGNI principle from file 04."}),"\n"]})]})}function h(e={}){let{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},8453(e,n,t){t.d(n,{R:()=>a,x:()=>o});var s=t(6540);let i={},r=s.createContext(i);function a(e){let n=s.useContext(r);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),s.createElement(r.Provider,{value:n},e.children)}}}]);